function countGoodNumbers(n) {
  const isPrime = (d) => {
    if (d < 2) return false;
    for (let k = 2; k * k <= d; k++) if (d % k === 0) return false;
    return true;
  };
  // Build the string one position at a time, multiplying by the number of digits allowed there.
  let count = 1;
  for (let position = 0; position < n; position++) {
    let allowed = 0;
    for (let digit = 0; digit <= 9; digit++) {
      if (position % 2 === 0 ? digit % 2 === 0 : isPrime(digit)) allowed++;
    }
    count = (count * allowed) % 1000000007;
  }
  return count;
}

