function generate(rand, size) {
  if (size === 'small') return [1 + Math.floor(rand() * (rand() < 0.7 ? 20 : 3000))];
  const LIMIT = 1e15;
  const shape = rand();
  if (shape < 0.25) return [LIMIT];
  if (shape < 0.5) return [LIMIT - Math.floor(rand() * 12)];
  return [1 + Math.floor(rand() * LIMIT)];
}
